def get_magic_item(name: str) -> dict | None:
    for i in ALL_MAGIC_ITEMS:
        if i["name"] == name:
            return i
    return None


def get_item_effect(name: str) -> dict | None:
    """Return mechanical effect for an item name, if any."""
    item = get_magic_item(name)
    if item and item.get("effect"):
        return item["effect"]
    return MAGIC_ITEM_EFFECTS.get(name)


def has_item_effect(name: str) -> bool:
    return get_item_effect(name) is not None


def items_by_rarity() -> dict:
    result = {}
    for item in ALL_MAGIC_ITEMS:
        r = item["rarity"]
        result.setdefault(r, []).append(item)
    return result

# Convenience alias used by other modules
MAGIC_ITEM_NAMES = [i["name"] for i in ALL_MAGIC_ITEMS]
